int initialize(F::Fixture&f,Sources&s,bool resume=false){A a(&s,f.core,s.guard(),{},s.api(),{});s.core=&f.core;s.store=&f.store;s.factory=&a;C::Initialization cap;int rc=resume?a.admitFreshResume(&cap):a.admitFreshEmpty(&cap);if(!rc)rc=f.core.initializeFreshEmpty(cap);if(rc==C::Retained)assert(!a.exitSafe());f.store.finishOperation();return rc;}
