void basic(){F::empty();{F::Fixture f;Sources s;s.reenter=true;assert(initialize(f,s)==C::Ok&&f.core.ready()&&f.core.baseline().origin()==C::Origin::FreshEmpty&&counter()==1);assert(F::put(f.core,"offline","first")==C::Ok);f.store.finishOperation();}F::reset();{F::Fixture f;assert(f.core.load()==C::Ok&&F::value(f.core,"offline")=="first");}receiptOnly();{F::Fixture f;assert(f.core.load()==C::Initializing);Sources s;assert(initialize(f,s,true)==C::Ok&&counter()==1);assert(F::put(f.core,"saved","newer")==C::Ok);f.store.finishOperation();}F::reset();{F::Fixture f;Sources s;assert(initialize(f,s,true)==C::Conflict&&f.core.load()==C::Ok&&F::value(f.core,"saved")=="newer");}puts("FreshEmpty: native-only/no SD/no entropy create, callback reentry refusal, distinct Initializing, checked resume and later edit preservation PASS");}
